  1675	// ─── MODULE NAV ───────────────────────────────────────────────
  1676	function renderModuleNav() {
  1677	  const nav = document.getElementById('moduleNav');
  1678	  nav.innerHTML = MODULES.map(function(m) {
  1679	    const done = m.days.filter(function(d) { return S.checkedDays[d.id]; }).length;
  1680	    const total = m.days.length;
  1681	    const isActive = m.id === S.activeModule;
  1682	    const isDone = done === total && total > 0;
  1683	    return '<div class="mnav-item' + (isActive ? ' active' : '') + (isDone ? ' done' : '') + '" onclick="setModule(' + m.id + ')">' +
  1684	      '<div class="mnav-dot"></div>' +
  1685	      '<div class="mnav-text">M' + m.id + ' — ' + m.title + '</div>' +
  1686	      '<div class="mnav-prog">' + done + '/' + total + '</div>' +
  1687	    '</div>';
  1688	  }).join('');
