  1875	  const blob = new Blob([JSON.stringify(S, null, 2)], {type: 'application/json'});
  1876	  const url = URL.createObjectURL(blob);
  1877	  const a = document.createElement('a');
  1878	  a.href = url;
  1879	  a.download = 'codize_' + new Date().toISOString().slice(0,10) + '.json';
  1880	  a.click();
  1881	  URL.revokeObjectURL(url);
  1882	  toast('Exported ↓');
