  1885	function importData(e) {
  1886	  const file = e.target.files[0];
  1887	  if (!file) return;
  1888	  const reader = new FileReader();
  1889	  reader.onload = function(ev) {
  1890	    try {
  1891	      S = Object.assign({}, S, JSON.parse(ev.target.result));
  1892	      saveState();
  1893	      init();
  1894	      toast('Imported ✓');
  1895	    } catch(err) { toast('Import failed'); }
  1896	  };
  1897	  reader.readAsText(file);
  1898	  e.target.value = '';
  1899	}
