    html += '</div>';
  }

  // JOURNAL
  html += '<div class="journal-wrap">';
  html += '<div class="journal-top">';
  html += '<span class="journal-lbl">Dev Journal — ' + day.num + '</span>';
  html += '<div style="display:flex;align-items:center">';
  html += '<span class="journal-saved" id="jsaved_' + day.id + '">Saved</span>';
  html += '<button class="journal-save" onclick="saveJournal(\'' + day.id + '\')">Save</button>';
  html += '</div>';
  html += '</div>';
  html += '<textarea class="journal-ta" id="jta_' + day.id + '" placeholder="What did you learn? What confused you? What clicked? 3–5 sentences minimum. If you can\'t explain it in plain English, you don\'t understand it yet.">' + (S.journals[day.id] || '') + '</textarea>';
  html += '</div>';

  html += '</div>'; // day-body
  html += '</div>'; // day-card

  return html;
}

function fmtCode(text) {
  return text.replace(/`([^`]+)`/g, '<code>$1</code>');
}

// ─── INTERACTIONS ─────────────────────────────────────────────
function toggleDay(id) {
  const body = document.getElementById('body_' + id);
  const tog = document.getElementById('tog_' + id);
  if (!body) return;
  body.classList.toggle('open');
  tog.classList.toggle('open');
}

function checkDay(id) {
  S.checkedDays[id] = !S.checkedDays[id];
  saveState();
  updateSidebar();
  renderContent();
  if (S.checkedDays[id]) toast('Day complete ✓');
}

function checkTask(dayId, idx) {
  const key = dayId + '_' + idx;
  S.checkedTasks[key] = !S.checkedTasks[key];
  saveState();
  renderContent();
}

function saveJournal(id) {
  const ta = document.getElementById('jta_' + id);
  if (!ta) return;
  S.journals[id] = ta.value;
  saveState();
  const saved = document.getElementById('jsaved_' + id);
  if (saved) { saved.style.display = 'inline'; setTimeout(function() { saved.style.display = 'none'; }, 2000); }
}

// ─── DATA ─────────────────────────────────────────────────────
function exportData() {
  const blob = new Blob([JSON.stringify(S, null, 2)], {type: 'application/json'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'codize_' + new Date().toISOString().slice(0,10) + '.json';
  a.click();
  URL.revokeObjectURL(url);
  toast('Exported ↓');
}

function importData(e) {
  const file = e.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = function(ev) {
    try {
      S = Object.assign({}, S, JSON.parse(ev.target.result));
      saveState();
      init();
      toast('Imported ✓');
    } catch(err) { toast('Import failed'); }
  };
  reader.readAsText(file);
  e.target.value = '';
}

// ─── TOAST ────────────────────────────────────────────────────
function toast(msg) {
  const el = document.getElementById('toast');
  el.textContent = msg;
  el.classList.add('show');
  setTimeout(function() { el.classList.remove('show'); }, 2200);
}

// ─── DATE ─────────────────────────────────────────────────────
function updateDate() {
  document.getElementById('todayDate').textContent =
    new Date().toLocaleDateString('en-US', {weekday:'short', month:'short', day:'numeric'});
  document.getElementById('statExpected').textContent = 'Day ' + getExpectedDay();
}

// ─── INIT ─────────────────────────────────────────────────────
function init() {
  loadState();
  updateDate();
  updateSidebar();
  renderContent();
  renderSessionLog();
  setInterval(updateCountdown, 1000);
  updateCountdown();
}

init();
</script>
</body>
</html>
