let S = {
  checkedDays: {},
  checkedTasks: {},
  journals: {},
  totalSeconds: 0,
  sessions: [],
  activeModule: 0,
  lastSessionDates: [],
};

function loadState() {
  try {
    const raw = localStorage.getItem('codize_v3');
    if (raw) S = Object.assign({}, S, JSON.parse(raw));
  } catch(e) {}
}

function saveState() {
  try { localStorage.setItem('codize_v3', JSON.stringify(S)); } catch(e) {}
}

let _timerRunning = false;
let _timerInterval = null;
let _sessionSecs = 0;
let _sessionStartTs = null;

function timerStart() {
  if (_timerRunning) return;
  _timerRunning = true;
  _sessionStartTs = Date.now();
  document.getElementById('btnStart').classList.add('hidden');
  document.getElementById('btnStop').classList.remove('hidden');
  document.getElementById('timerDisp').classList.add('running');
  _timerInterval = setInterval(function() {
    _sessionSecs = Math.floor((Date.now() - _sessionStartTs) / 1000);
    document.getElementById('timerDisp').textContent = fmtTime(_sessionSecs);
  }, 1000);
  toast('Session started');
}

function timerStop() {
  if (!_timerRunning) return;
  _timerRunning = false;
  clearInterval(_timerInterval);
  _timerInterval = null;
  document.getElementById('btnStart').classList.remove('hidden');
  document.getElementById('btnStop').classList.add('hidden');
  document.getElementById('timerDisp').classList.remove('running');
  S.totalSeconds += _sessionSecs;
  const now = new Date();
  const dateStr = now.toLocaleDateString('en-US', {month:'short', day:'numeric'});
  const timeStr = now.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'});
  S.sessions.unshift({ date: dateStr + ' ' + timeStr, dur: fmtTime(_sessionSecs) });
  if (S.sessions.length > 20) S.sessions.length = 20;
  const todayStr = now.toDateString();
  if (!S.lastSessionDates) S.lastSessionDates = [];
  if (!S.lastSessionDates.includes(todayStr)) {
    S.lastSessionDates.push(todayStr);
    if (S.lastSessionDates.length > 60) S.lastSessionDates = S.lastSessionDates.slice(-60);
  }
  _sessionSecs = 0;
  _sessionStartTs = null;
  saveState();
  updateSidebar();
  renderSessionLog();
  toast('Session saved ✓');
}

function timerReset() {
  if (_timerRunning) { timerStop(); }
  _sessionSecs = 0;
  document.getElementById('timerDisp').textContent = '00:00:00';
  document.getElementById('timerDisp').classList.remove('running');
  document.getElementById('btnStart').classList.remove('hidden');
  document.getElementById('btnStop').classList.add('hidden');
}

function fmtTime(secs) {
  const h = Math.floor(secs / 3600);
  const m = Math.floor((secs % 3600) / 60);
  const s = secs % 60;
  return [h, m, s].map(function(n) { return String(n).padStart(2, '0'); }).join(':');
}

function renderSessionLog() {
  const el = document.getElementById('sessionLog');
  if (!el) return;
  el.innerHTML = (S.sessions || []).slice(0, 8).map(function(s) {
    return '<div class="session-entry"><span>' + s.date + '</span><span>' + s.dur + '</span></div>';
  }).join('');
}

function updateCountdown() {
  const now = new Date();
  const diff = DEADLINE - now;
  if (diff <= 0) {
    ['cdD','cdH','cdM','cdS'].forEach(function(id) { document.getElementById(id).textContent = '00'; });
    return;
  }
  const d = Math.floor(diff / 86400000);
  const h = Math.floor((diff % 86400000) / 3600000);
  const m = Math.floor((diff % 3600000) / 60000);
  const sc = Math.floor((diff % 60000) / 1000);
  document.getElementById('cdD').textContent = String(d).padStart(2,'0');
  document.getElementById('cdH').textContent = String(h).padStart(2,'0');
  document.getElementById('cdM').textContent = String(m).padStart(2,'0');
  document.getElementById('cdS').textContent = String(sc).padStart(2,'0');
}

function getExpectedDay() {
  const now = new Date();
  const elapsed = Math.floor((now - START_DATE) / 86400000);
  return Math.min(elapsed + 1, TOTAL_DAYS);
}

function getActualDay() {
  return Object.values(S.checkedDays).filter(Boolean).length;
}

function getStreak() {
  if (!S.lastSessionDates || S.lastSessionDates.length === 0) return 0;
  const today = new Date();
  let streak = 0;
  for (let i = 0; i < 60; i++) {
    const d = new Date(today);
    d.setDate(d.getDate() - i);
    if (S.lastSessionDates.includes(d.toDateString())) {
      streak++;
    } else {
      break;
    }
  }
  return streak;
}

function updatePace() {
  const expected = getExpectedDay();
  const actual = getActualDay();
  const gap = actual - expected;

  document.getElementById('paceTarget').textContent = 'Day ' + expected;
  document.getElementById('paceActual').textContent = 'Day ' + actual;

  const fillPct = Math.min((actual / TOTAL_DAYS) * 100, 100);
  document.getElementById('paceBar').style.width = fillPct + '%';

  const msgEl = document.getElementById('paceMsg');
  const badgeEl = document.getElementById('paceBadge');
  const gapEl = document.getElementById('statGap');

  if (gap >= 2) {
    msgEl.textContent = '+' + gap + ' days ahead of schedule';
    msgEl.style.background = 'var(--done-bg)';
    msgEl.style.color = 'var(--done)';
    badgeEl.textContent = 'Ahead';
    badgeEl.className = 'pace-badge pace-ahead';
    gapEl.textContent = '+' + gap;
    gapEl.style.color = 'var(--done)';
  } else if (gap >= -1) {
    msgEl.textContent = 'On track — keep the pace';
    msgEl.style.background = 'var(--accent-bg)';
    msgEl.style.color = 'var(--accent)';
    badgeEl.textContent = 'On Track';
    badgeEl.className = 'pace-badge pace-on';
    gapEl.textContent = gap === 0 ? '0' : gap;
    gapEl.style.color = 'var(--accent)';
  } else if (gap >= -3) {
    msgEl.textContent = Math.abs(gap) + ' days behind — push harder this week';
    msgEl.style.background = 'var(--warn-bg)';
    msgEl.style.color = 'var(--warn)';
    badgeEl.textContent = 'Behind';
    badgeEl.className = 'pace-behind';
    gapEl.textContent = gap;
    gapEl.style.color = 'var(--warn)';
  } else {
    msgEl.textContent = Math.abs(gap) + ' days behind — catch up now';
    msgEl.style.background = 'var(--danger-bg)';
    msgEl.style.color = 'var(--danger)';
    badgeEl.textContent = 'Catch Up';
    badgeEl.className = 'pace-badge pace-late';
    gapEl.textContent = gap;
    gapEl.style.color = 'var(--danger)';
  }
}

function updateSidebar() {
  const actual = getActualDay();
  const totalH = Math.floor(S.totalSeconds / 3600);
  const totalM = Math.floor((S.totalSeconds % 3600) / 60);
  const streak = getStreak();

  document.getElementById('statDays').textContent = actual + '/' + TOTAL_DAYS;
  document.getElementById('statHours').textContent = totalH + 'h ' + totalM + 'm';
  document.getElementById('statStreak').textContent = streak;
  document.getElementById('totalTime').textContent = totalH + 'h ' + totalM + 'm';

  updatePace();
  renderModuleNav();
}

function renderModuleNav() {
  const nav = document.getElementById('moduleNav');
  nav.innerHTML = MODULES.map(function(m) {
    const done = m.days.filter(function(d) { return S.checkedDays[d.id]; }).length;
    const total = m.days.length;
    const isActive = m.id === S.activeModule;
    const isDone = done === total && total > 0;
    return '<div class="mnav-item' + (isActive ? ' active' : '') + (isDone ? ' done' : '') + '" onclick="setModule(' + m.id + ')">' +
      '<div class="mnav-dot"></div>' +
      '<div class="mnav-text">M' + m.id + ' — ' + m.title + '</div>' +
      '<div class="mnav-prog">' + done + '/' + total + '</div>' +
    '</div>';
  }).join('');
}

function setModule(id) {
  S.activeModule = id;
  saveState();
  renderModuleNav();
  renderContent();
}

function renderContent() {
  const mod = MODULES[S.activeModule];
  const done = mod.days.filter(function(d) { return S.checkedDays[d.id]; }).length;
  const total = mod.days.length;
  const pct = total > 0 ? Math.round((done/total)*100) : 0;
  const expectedDay = getExpectedDay();

  let html = '';
  html += '<div class="mod-eyebrow">Module ' + mod.id + ' / Phase 1 — v2.1</div>';
  html += '<div class="mod-title">' + mod.title + '</div>';
  html += '<div class="mod-desc">' + mod.desc + '</div>';
  html += '<div class="mod-meta">';
  html += '<div class="mod-meta-item">Duration: <strong>' + mod.duration + '</strong></div>';
  html += '<div class="mod-meta-item">Days: <strong>' + mod.dayLabel + '</strong></div>';
  html += '<div class="mod-meta-item">Progress: <strong>' + done + '/' + total + '</strong></div>';
  html += '</div>';
  html += '<div class="mod-progress-bar"><div class="mod-progress-fill" style="width:' + pct + '%"></div></div>';

  mod.days.forEach(function(day) {
    html += renderDay(day, mod, expectedDay);
  });

  document.getElementById('contentArea').innerHTML = html;
}

function getTodayDayIndex() {
  const expected = getExpectedDay();
  let count = 0;
  for (let mi = 0; mi < MODULES.length; mi++) {
    for (let di = 0; di < MODULES[mi].days.length; di++) {
      count++;
      if (count === expected) return { mi, di, dayId: MODULES[mi].days[di].id };
    }
  }
  return null;
}

function renderDay(day, mod, expectedDay) {
  const isDone = !!S.checkedDays[day.id];

  let globalIdx = 0;
  let isToday = false;
  outer: for (let mi = 0; mi < MODULES.length; mi++) {
    for (let di = 0; di < MODULES[mi].days.length; di++) {
      globalIdx++;
      if (MODULES[mi].days[di].id === day.id) {
        isToday = (globalIdx === expectedDay);
        break outer;
      }
    }
  }

  const isOpen = !isDone || isToday;

  let html = '<div class="day-card' + (isDone ? ' done-card' : '') + '" id="card_' + day.id + '">';

  html += '<div class="day-head" onclick="toggleDay(\'' + day.id + '\')">';
  html += '<div class="day-chk' + (isDone ? ' chk-done' : '') + '" onclick="event.stopPropagation();checkDay(\'' + day.id + '\')">' + (isDone ? '✓' : '') + '</div>';
  html += '<div class="day-info">';
  html += '<div class="day-num-lbl">' + day.num + '</div>';
  html += '<div class="day-title-text">' + day.title + '</div>';
  html += '</div>';
  if (isToday && !isDone) html += '<span class="today-badge">Today\'s Target</span>';
  html += '<div class="day-toggle-icon' + (isOpen ? ' open' : '') + '" id="tog_' + day.id + '">▼</div>';
  html += '</div>';

  html += '<div class="day-body' + (isOpen ? ' open' : '') + '" id="body_' + day.id + '">';

  if (day.note) {
    html += '<div class="note-box">' + day.note + '</div>';
  }

  if (day.securityNote) {
    html += '<div class="security-box"><div class="security-box-title">⚑ Security Constraint</div>' + day.securityNote + '</div>';
  }

  if (day.concepts && day.concepts.length > 0) {
    html += '<div class="sec-label">Exact Concepts</div>';
    html += '<ul class="concept-list">';
    day.concepts.forEach(function(c) {
      html += '<li>' + fmtCode(c) + '</li>';
    });
    html += '</ul>';
  }

  if (day.codeBlock) {
    html += '<div class="sec-label">Project Structure</div>';
    html += '<div class="code-block">' + day.codeBlock + '</div>';
  }

  if (day.resources && day.resources.length > 0) {
    html += '<div class="sec-label">Resources</div>';
    html += '<ul class="resource-list">';
    day.resources.forEach(function(r) {
      html += '<li><a href="' + r.url + '" target="_blank" rel="noopener">' + r.text + '</a><span class="res-note">' + r.note + '</span></li>';
    });
    html += '</ul>';
  }

  if (day.checkpoint) {
    html += '<div class="checkpoint-box">';
    html += '<div class="checkpoint-title-row">';
    html += '<span class="checkpoint-icon">Checkpoint</span>';
    html += '<span class="checkpoint-title-text">' + day.checkpoint.title + '</span>';
    html += '</div>';
    day.checkpoint.items.forEach(function(item, i) {
      const key = day.id + '_' + i;
      const done = !!S.checkedTasks[key];
      html += '<div class="chk-item' + (done ? ' chk-done-item' : '') + '" onclick="checkTask(\'' + day.id + '\',' + i + ')">';
      html += '<div class="chk-sq">' + (done ? '✓' : '') + '</div>';
      html += '<span>' + fmtCode(item) + '</span>';
      html += '</div>';
    });
    if (day.checkpoint.challenge) {
      html += '<div class="challenge-box"><div class="challenge-label">Challenge</div>' + day.checkpoint.challenge + '</div>';
    }
    html += '</div>';
  }

  html += '<div class="journal-wrap">';
  html += '<div class="journal-top">';
  html += '<span class="journal-lbl">Dev Journal — ' + day.num + '</span>';
  html += '<div style="display:flex;align-items:center">';
  html += '<span class="journal-saved" id="jsaved_' + day.id + '">Saved</span>';
  html += '<button class="journal-save" onclick="saveJournal(\'' + day.id + '\')">Save</button>';
  html += '</div>';
  html += '</div>';
  html += '<textarea class="journal-ta" id="jta_' + day.id + '" placeholder="What did you learn? What confused you? What clicked? 3–5 sentences minimum. If you can\'t explain it in plain English, you don\'t understand it yet.">' + (S.journals[day.id] || '') + '</textarea>';
  html += '</div>';

  html += '</div>';
  html += '</div>';

  return html;
}

function fmtCode(text) {
  return text.replace(/`([^`]+)`/g, '<code>$1</code>');
}

function toggleDay(id) {
  const body = document.getElementById('body_' + id);
  const tog = document.getElementById('tog_' + id);
  if (!body) return;
  body.classList.toggle('open');
  tog.classList.toggle('open');
}

function checkDay(id) {
  S.checkedDays[id] = !S.checkedDays[id];
  saveState();
  updateSidebar();
  renderContent();
  if (S.checkedDays[id]) toast('Day complete ✓');
}

function checkTask(dayId, idx) {
  const key = dayId + '_' + idx;
  S.checkedTasks[key] = !S.checkedTasks[key];
  saveState();
  renderContent();
}

function saveJournal(id) {
  const ta = document.getElementById('jta_' + id);
  if (!ta) return;
  S.journals[id] = ta.value;
  saveState();
  const saved = document.getElementById('jsaved_' + id);
  if (saved) { saved.style.display = 'inline'; setTimeout(function() { saved.style.display = 'none'; }, 2000); }
}

function exportData() {
  const blob = new Blob([JSON.stringify(S, null, 2)], {type: 'application/json'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'codize_' + new Date().toISOString().slice(0,10) + '.json';
  a.click();
  URL.revokeObjectURL(url);
