}

function importData(e) {
  const file = e.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = function(ev) {
    try {
      S = Object.assign({}, S, JSON.parse(ev.target.result));
      saveState();
      init();
      toast('Imported ✓');
    } catch(err) { toast('Import failed'); }
  };
  reader.readAsText(file);
  e.target.value = '';
}

