/* SECTION LABEL */
.sec-label {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 10px; text-transform: uppercase;
  letter-spacing: 0.1em; color: var(--ink3);
  margin: 16px 0 8px;
}

/* NOTE */
.note-box {
  background: var(--warn-bg);
  border-left: 2px solid var(--warn);
  padding: 10px 14px;
  margin-top: 14px;
  font-size: 12px; color: var(--ink2); line-height: 1.6;
}

/* CONCEPT LIST */
.concept-list { list-style: none; }

.concept-list li {
  display: flex; gap: 10px;
  padding: 6px 0;
  font-size: 12.5px; color: var(--ink2); line-height: 1.5;
  border-bottom: 1px solid var(--border);
}

.concept-list li:last-child { border-bottom: none; }

.concept-list li::before {
  content: '—';
  color: var(--accent); flex-shrink: 0;
  font-size: 11px; margin-top: 2px;
  font-family: 'IBM Plex Mono', monospace;
}

code {
  background: #1a1530;
  padding: 1px 5px; border-radius: 2px;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 11.5px; color: var(--accent);
}

