  --accent: #a78bfa;
  --accent-bg: #1a1530;
  --border: #1e1b2e;
  --surface: #111018;
  --done-bg: #0f1f18;
  --done: #4ade80;
  --warn-bg: #1c1810;
  --warn: #fbbf24;
  --danger-bg: #1f1015;
  --danger: #f87171;
}

body {
  background: var(--bg);
  color: var(--ink);
  font-family: 'DM Sans', sans-serif;
  font-size: 14px;
  line-height: 1.6;
  min-height: 100vh;
}

/* SCROLLBAR */
::-webkit-scrollbar { width: 4px; height: 4px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 2px; }

/* TOP BAR */
.topbar {
  position: sticky; top: 0; z-index: 200;
  background: var(--bg);
  border-bottom: 1px solid var(--border);
  display: flex; align-items: center; gap: 0;
  height: 52px;
}

.topbar-logo {
  padding: 0 24px;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 13px; font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--ink);
  border-right: 1px solid var(--border);
  height: 100%; display: flex; align-items: center;
  white-space: nowrap;
}

.topbar-logo span { color: var(--accent); }

.topbar-status {
  padding: 0 20px;
  display: flex; align-items: center; gap: 20px;
  flex: 1; height: 100%;
  border-right: 1px solid var(--border);
  overflow-x: auto;
}

.status-item {
  display: flex; flex-direction: column;
  white-space: nowrap;
}

.status-val {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 15px; font-weight: 600;
  line-height: 1.2;
}

.status-lbl {
  font-size: 10px; color: var(--ink3);
  text-transform: uppercase; letter-spacing: 0.08em;
}

.status-div { width: 1px; height: 28px; background: var(--border); flex-shrink: 0; }

.topbar-right {
  padding: 0 20px;
  display: flex; align-items: center; gap: 10px;
}

/* PACE BADGE */
.pace-badge {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 10px; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.06em;
  padding: 3px 10px; border-radius: 2px;
}

.pace-ahead { background: var(--done-bg); color: var(--done); }
.pace-on { background: var(--accent-bg); color: var(--accent); }
.pace-behind { background: var(--warn-bg); color: var(--warn); }
.pace-late { background: var(--danger-bg); color: var(--danger); }

/* DATE */
.topbar-date {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 11px; color: var(--ink3);
}

/* LAYOUT */
.layout {
  display: grid;
  grid-template-columns: 256px 1fr;
  min-height: calc(100vh - 52px);
}

/* SIDEBAR */
.sidebar {
  border-right: 1px solid var(--border);
  display: flex; flex-direction: column;
  position: sticky; top: 52px;
  height: calc(100vh - 52px);
  overflow-y: auto;
}

/* COUNTDOWN */
.countdown-block {
  padding: 20px 20px 16px;
  border-bottom: 1px solid var(--border);
}

.countdown-label {
  font-size: 10px; text-transform: uppercase;
  letter-spacing: 0.1em; color: var(--ink3);
  margin-bottom: 8px;
  font-family: 'IBM Plex Mono', monospace;
}

.countdown-nums {
  display: flex; gap: 0; align-items: baseline;
}

.cd-unit { text-align: center; }

.cd-num {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 22px; font-weight: 600;
  color: var(--ink); line-height: 1;
  display: block;
}

.cd-sub {
  font-size: 9px; color: var(--ink3);
  text-transform: uppercase; letter-spacing: 0.08em;
  display: block; margin-top: 2px;
}

.cd-sep {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 18px; color: var(--border);
  padding: 0 4px; padding-bottom: 8px;
  align-self: center;
}

/* WHERE I SHOULD BE */
.pace-block {
  padding: 16px 20px;
  border-bottom: 1px solid var(--border);
}

.pace-title {
  font-size: 10px; text-transform: uppercase;
  letter-spacing: 0.1em; color: var(--ink3);
  font-family: 'IBM Plex Mono', monospace;
  margin-bottom: 10px;
}

.pace-row {
  display: flex; justify-content: space-between;
  align-items: baseline; margin-bottom: 4px;
}

.pace-key { font-size: 12px; color: var(--ink2); }
.pace-val { font-family: 'IBM Plex Mono', monospace; font-size: 12px; font-weight: 600; }

.pace-bar-wrap {
  height: 3px; background: var(--border);
  border-radius: 2px; margin: 10px 0 8px;
  overflow: hidden;
}

.pace-bar-fill {
  height: 100%; border-radius: 2px;
  background: var(--accent);
  transition: width 0.4s ease;
}

.pace-gap-msg {
  font-size: 11px;
  padding: 6px 10px; border-radius: 2px;
  font-family: 'IBM Plex Mono', monospace;
  line-height: 1.4;
}

/* TIMER */
.timer-block {
  padding: 16px 20px;
  border-bottom: 1px solid var(--border);
}

.timer-title {
  font-size: 10px; text-transform: uppercase;
  letter-spacing: 0.1em; color: var(--ink3);
  font-family: 'IBM Plex Mono', monospace;
  margin-bottom: 10px;
}

.timer-display {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 28px; font-weight: 600;
  color: var(--ink); letter-spacing: 0.04em;
  margin-bottom: 10px; line-height: 1;
}

.timer-display.running { color: var(--accent); }

.timer-btns {
  display: flex; gap: 6px; margin-bottom: 8px;
}

.tbtn {
  flex: 1; padding: 7px 0;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--ink2); border-radius: 2px;
  cursor: pointer; font-family: 'IBM Plex Mono', monospace;
  font-size: 10px; text-transform: uppercase;
  letter-spacing: 0.06em; transition: all 0.12s;
}

.tbtn:hover { border-color: var(--ink); color: var(--ink); }
.tbtn.primary { background: var(--accent); border-color: var(--accent); color: var(--bg); }
.tbtn.primary:hover { background: #c4b0fd; }
.tbtn.stop { border-color: var(--accent); color: var(--accent); }
.tbtn.stop:hover { background: var(--accent-bg); }

.hidden { display: none !important; }

.timer-total {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 10px; color: var(--ink3);
  margin-bottom: 8px;
}

.timer-total strong { color: var(--ink); }

.session-log { max-height: 80px; overflow-y: auto; }

.session-entry {
  display: flex; justify-content: space-between;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 10px; color: var(--ink3);
  padding: 3px 0;
  border-bottom: 1px solid var(--border);
}

.session-entry:last-child { border-bottom: none; }

/* STREAK */
.streak-block {
  padding: 14px 20px;
  border-bottom: 1px solid var(--border);
  display: flex; align-items: center; justify-content: space-between;
}

.streak-label { font-size: 11px; color: var(--ink2); }

.streak-val {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 18px; font-weight: 600;
  color: var(--accent);
}

.streak-sub { font-size: 9px; color: var(--ink3); text-align: right; }

/* MODULE NAV */
.module-nav { flex: 1; overflow-y: auto; padding: 8px 0; }

.mnav-item {
  display: flex; align-items: center; gap: 10px;
  padding: 9px 20px;
  cursor: pointer; transition: background 0.1s;
  border-left: 2px solid transparent;
}

.mnav-item:hover { background: var(--border); }
.mnav-item.active { background: var(--accent-bg); border-left-color: var(--accent); }
.mnav-item.done { border-left-color: var(--done); }

.mnav-dot {
  width: 7px; height: 7px; border-radius: 50%;
  border: 1.5px solid var(--ink3); flex-shrink: 0;
  transition: all 0.15s;
}

.mnav-item.active .mnav-dot { border-color: var(--accent); background: var(--accent); }
.mnav-item.done .mnav-dot { border-color: var(--done); background: var(--done); }

.mnav-text { flex: 1; font-size: 12px; color: var(--ink2); line-height: 1.3; }
.mnav-item.active .mnav-text { color: var(--accent); font-weight: 500; }
.mnav-item.done .mnav-text { color: var(--done); }

.mnav-prog {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 10px; color: var(--ink3);
}

/* SIDEBAR FOOTER */
.sidebar-footer {
  padding: 12px 20px;
  border-top: 1px solid var(--border);
  display: flex; gap: 6px;
}

.sfbtn {
  flex: 1; padding: 7px 0;
  border: 1px solid var(--border);
  background: transparent; color: var(--ink2);
  border-radius: 2px; cursor: pointer;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 10px; text-transform: uppercase;
  letter-spacing: 0.05em; transition: all 0.12s;
}

.sfbtn:hover { border-color: var(--ink); color: var(--ink); }

/* CONTENT */
.content { padding: 40px 48px; max-width: 800px; }

/* MODULE HEADER */
.mod-eyebrow {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 10px; text-transform: uppercase;
  letter-spacing: 0.12em; color: var(--ink3);
  margin-bottom: 8px;
}

.mod-title {
  font-family: 'Instrument Serif', serif;
  font-size: 36px; line-height: 1.1;
  letter-spacing: -0.01em;
  margin-bottom: 10px;
}

.mod-desc {
  font-size: 14px; color: var(--ink2);
  line-height: 1.7; max-width: 540px;
  margin-bottom: 20px;
}

.mod-meta {
  display: flex; gap: 24px; margin-bottom: 6px;
}

.mod-meta-item {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 11px; color: var(--ink3);
}

.mod-meta-item strong { color: var(--ink); }

.mod-progress-bar {
  height: 2px; background: var(--border);
  margin: 16px 0 32px; border-radius: 1px; overflow: hidden;
}

.mod-progress-fill {
  height: 100%; background: var(--accent);
  transition: width 0.4s ease;
}

/* DAY CARD */
.day-card {
  border: 1px solid var(--border);
  border-radius: 3px;
  margin-bottom: 10px;
  background: var(--surface);
  overflow: hidden;
  transition: border-color 0.15s;
}

.day-card.done-card { border-color: #c5dfc9; }
.day-card:hover { border-color: #bbb; }

.day-head {
  display: flex; align-items: center; gap: 12px;
  padding: 14px 16px; cursor: pointer;
  user-select: none;
}

.day-chk {
  width: 20px; height: 20px; border-radius: 50%;
  border: 1.5px solid var(--border);
  display: flex; align-items: center; justify-content: center;
  font-size: 10px; color: transparent;
  cursor: pointer; flex-shrink: 0;
  transition: all 0.15s;
}

.day-chk:hover { border-color: var(--done); }
.day-chk.chk-done { background: var(--done); border-color: var(--done); color: white; }

.day-info { flex: 1; }

.day-num-lbl {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 10px; color: var(--ink3);
  text-transform: uppercase; letter-spacing: 0.06em;
}

.day-title-text {
  font-size: 14px; font-weight: 500; color: var(--ink);
  margin-top: 1px;
}

.day-toggle-icon {
  font-size: 10px; color: var(--ink3);
  transition: transform 0.2s;
}

.day-toggle-icon.open { transform: rotate(180deg); }

/* TODAY INDICATOR */
.today-badge {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 9px; text-transform: uppercase;
  letter-spacing: 0.08em;
  background: var(--accent); color: white;
  padding: 2px 7px; border-radius: 2px;
}

/* DAY BODY */
.day-body { display: none; padding: 0 16px 16px; border-top: 1px solid var(--border); }
.day-body.open { display: block; }

/* SECTION LABEL */
.sec-label {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 10px; text-transform: uppercase;
  letter-spacing: 0.1em; color: var(--ink3);
  margin: 16px 0 8px;
}

/* NOTE */
.note-box {
  background: var(--warn-bg);
  border-left: 2px solid var(--warn);
  padding: 10px 14px;
  margin-top: 14px;
  font-size: 12px; color: var(--ink2); line-height: 1.6;
}

/* CONCEPT LIST */
.concept-list { list-style: none; }

.concept-list li {
  display: flex; gap: 10px;
  padding: 6px 0;
  font-size: 12.5px; color: var(--ink2); line-height: 1.5;
  border-bottom: 1px solid var(--border);
}

.concept-list li:last-child { border-bottom: none; }

.concept-list li::before {
  content: '—';
  color: var(--accent); flex-shrink: 0;
  font-size: 11px; margin-top: 2px;
  font-family: 'IBM Plex Mono', monospace;
}

code {
  background: #1a1530;
  padding: 1px 5px; border-radius: 2px;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 11.5px; color: var(--accent);
}

/* RESOURCES */
.resource-list { list-style: none; }

.resource-list li {
  display: flex; align-items: baseline; gap: 10px;
  padding: 7px 0; border-bottom: 1px solid var(--border);
  font-size: 12px;
}

.resource-list li:last-child { border-bottom: none; }

.resource-list a {
  color: var(--ink);
  text-decoration: underline;
  text-decoration-color: var(--border);
  text-underline-offset: 2px;
  transition: text-decoration-color 0.15s;
}

.resource-list a:hover { text-decoration-color: var(--accent); color: var(--accent); }

.res-note { color: var(--ink3); font-size: 11px; margin-left: auto; white-space: nowrap; }

/* CODE BLOCK */
.code-block {
  background: #060509;
  color: #c4b8f0;
  padding: 16px;
  border-radius: 3px;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 11.5px; line-height: 1.7;
  overflow-x: auto;
  white-space: pre;
  margin-top: 4px;
}

/* CHECKPOINT */
.checkpoint-box {
  border: 1px solid #2a2540;
  border-radius: 3px; padding: 16px;
  margin-top: 16px;
  background: #0f0d1a;
}

.checkpoint-title-row {
  display: flex; align-items: center; gap: 8px;
  margin-bottom: 12px;
}

.checkpoint-icon {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 9px; text-transform: uppercase;
  letter-spacing: 0.1em;
  background: var(--accent); color: var(--bg);
  padding: 3px 8px; border-radius: 2px;
}

.checkpoint-title-text {
  font-size: 12px; font-weight: 500; color: var(--ink);
}

.chk-item {
  display: flex; align-items: flex-start; gap: 10px;
  padding: 7px 0; border-bottom: 1px solid var(--border);
  font-size: 12.5px; color: var(--ink2);
  cursor: pointer; transition: color 0.12s; line-height: 1.5;
}

.chk-item:last-child { border-bottom: none; }
.chk-item:hover { color: var(--ink); }
.chk-item.chk-done-item { color: var(--done); }

.chk-sq {
  width: 14px; height: 14px;
  border: 1.5px solid var(--border); border-radius: 2px;
  display: flex; align-items: center; justify-content: center;
  font-size: 9px; color: transparent; flex-shrink: 0;
  margin-top: 2px; transition: all 0.12s;
}

.chk-item.chk-done-item .chk-sq {
  background: var(--done); border-color: var(--done); color: white;
}

/* CHALLENGE */
.challenge-box {
  border-left: 2px solid var(--accent);
  padding: 10px 14px; margin-top: 12px;
  background: var(--accent-bg);
  font-size: 12.5px; color: var(--ink2); line-height: 1.6;
}

.challenge-label {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 9px; text-transform: uppercase;
  letter-spacing: 0.1em; color: var(--accent);
  margin-bottom: 6px;
}

/* JOURNAL */
.journal-wrap {
  margin-top: 16px;
  border: 1px solid var(--border); border-radius: 3px;
  overflow: hidden; background: var(--surface);
}

.journal-top {
  display: flex; align-items: center; justify-content: space-between;
  padding: 8px 12px; border-bottom: 1px solid var(--border);
  background: #0a0910;
}

.journal-lbl {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 10px; text-transform: uppercase;
  letter-spacing: 0.08em; color: var(--ink3);
}

.journal-save {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 10px; text-transform: uppercase;
  letter-spacing: 0.05em;
  border: 1px solid var(--border);
  background: transparent; color: var(--ink2);
  padding: 3px 10px; border-radius: 2px;
  cursor: pointer; transition: all 0.12s;
}

.journal-save:hover { border-color: var(--ink); color: var(--ink); }

.journal-saved {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 9px; color: var(--done);
  display: none; margin-left: 8px;
}

textarea.journal-ta {
  width: 100%; min-height: 80px;
  border: none; outline: none;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 12px; line-height: 1.6;
  padding: 12px; color: var(--ink2);
  background: transparent; resize: vertical;
}

textarea.journal-ta::placeholder { color: var(--ink3); }

/* TOAST */
.toast {
  position: fixed; bottom: 24px; right: 24px;
  background: var(--accent); color: var(--bg);
  padding: 10px 16px; border-radius: 3px;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 11px; z-index: 999;
  transform: translateY(60px); opacity: 0;
  transition: all 0.25s; pointer-events: none;
}

.toast.show { transform: translateY(0); opacity: 1; }
</style>
</head>
<body>

<div class="toast" id="toast"></div>

<!-- TOP BAR -->
<div class="topbar">
  <div class="topbar-logo">codize<span>.</span>app</div>
  <div class="topbar-status">
    <div class="status-item">
      <span class="status-val" id="statDays">0/45</span>
      <span class="status-lbl">Days Done</span>
    </div>
    <div class="status-div"></div>
    <div class="status-item">
      <span class="status-val" id="statExpected">—</span>
      <span class="status-lbl">Expected Day</span>
    </div>
    <div class="status-div"></div>
    <div class="status-item">
      <span class="status-val" id="statGap">—</span>
      <span class="status-lbl">Gap</span>
    </div>
    <div class="status-div"></div>
    <div class="status-item">
      <span class="status-val" id="statHours">0h</span>
      <span class="status-lbl">Total Hours</span>
    </div>
    <div class="status-div"></div>
    <div class="status-item">
      <span class="status-val" id="statStreak">0</span>
      <span class="status-lbl">Day Streak</span>
    </div>
  </div>
  <div class="topbar-right">
    <span class="pace-badge pace-on" id="paceBadge">Calculating...</span>
    <span class="topbar-date" id="todayDate"></span>
  </div>
</div>

<!-- LAYOUT -->
<div class="layout">

  <!-- SIDEBAR -->
  <aside class="sidebar">

    <!-- COUNTDOWN -->
    <div class="countdown-block">
      <div class="countdown-label">Phase 1 ends Aug 1, 2025</div>
      <div class="countdown-nums">
        <div class="cd-unit">
          <span class="cd-num" id="cdD">--</span>
          <span class="cd-sub">Days</span>
        </div>
        <span class="cd-sep">:</span>
        <div class="cd-unit">
          <span class="cd-num" id="cdH">--</span>
          <span class="cd-sub">Hrs</span>
        </div>
        <span class="cd-sep">:</span>
        <div class="cd-unit">
          <span class="cd-num" id="cdM">--</span>
          <span class="cd-sub">Min</span>
        </div>
        <span class="cd-sep">:</span>
        <div class="cd-unit">
          <span class="cd-num" id="cdS">--</span>
          <span class="cd-sub">Sec</span>
        </div>
      </div>
    </div>

    <!-- WHERE SHOULD I BE -->
    <div class="pace-block">
      <div class="pace-title">Where You Should Be</div>
      <div class="pace-row">
        <span class="pace-key">Today's target day</span>
        <span class="pace-val" id="paceTarget">—</span>
      </div>
      <div class="pace-row">
        <span class="pace-key">Your actual day</span>
        <span class="pace-val" id="paceActual">—</span>
      </div>
      <div class="pace-bar-wrap">
        <div class="pace-bar-fill" id="paceBar" style="width:0%"></div>
      </div>
      <div class="pace-gap-msg" id="paceMsg"></div>
    </div>

    <!-- TIMER -->
    <div class="timer-block">
      <div class="timer-title">Session Timer</div>
      <div class="timer-display" id="timerDisp">00:00:00</div>
      <div class="timer-btns">
        <button class="tbtn primary" id="btnStart" onclick="timerStart()">Start</button>
        <button class="tbtn stop hidden" id="btnStop" onclick="timerStop()">Stop</button>
        <button class="tbtn" onclick="timerReset()">Reset</button>
      </div>
      <div class="timer-total">Total: <strong id="totalTime">0h 0m</strong></div>
      <div class="session-log" id="sessionLog"></div>
    </div>

    <!-- MODULE NAV -->
    <div class="module-nav" id="moduleNav"></div>

    <!-- FOOTER -->
    <div class="sidebar-footer">
      <button class="sfbtn" onclick="exportData()">↓ Export</button>
      <button class="sfbtn" onclick="document.getElementById('fileIn').click()">↑ Import</button>
      <input type="file" id="fileIn" accept=".json" style="display:none" onchange="importData(event)">
    </div>

  </aside>

  <!-- CONTENT -->
  <div class="content" id="contentArea"></div>

</div>

<script>
// ─── CONSTANTS ───────────────────────────────────────────────
const START_DATE = new Date('2026-05-25T00:00:00');
const DEADLINE   = new Date('2026-08-01T23:59:59');
const TOTAL_DAYS = 45;

// ─── DATA ─────────────────────────────────────────────────────
const MODULES = [
  {
    id: 0, title: 'Environment Setup',
    dayLabel: '1', duration: '1 day',
